import pathlib,json,re,collections,sys
sys.stdout.reconfigure(encoding='utf-8')
M='ro316-penyesuaian-setting-komisi-agen'
OUT=pathlib.Path('output')/M
analysis=(OUT/f'{M}.analysis.md').read_text(encoding='utf-8')
REQ={m[0]:m[1] for m in re.findall(r'^\| (REQ-\d{3}) \| (.*?) \|',analysis,re.M)}
UI={}
for screen,body in re.findall(r'^### ([a-z][a-z0-9-]+)\n(.*?)(?=^### |^## |\Z)',analysis,re.M|re.S):
    UI[screen]={}
    for name,role,testid in re.findall(r'^\| (.*?) \| (.*?) \| `(.*?)` \|',body,re.M): UI[screen][name]={'role':role,'name':name,'testid':testid}
S=[]
route='Balikpapan → Parepare'
reverse='Parepare → Balikpapan'
adult='Ekonomi Lesehan Dewasa'
child='Ekonomi Lesehan Anak'
car='Gol. III-A (Sedan, Jeep, Pick-up)'
key={'rute':route,'jenisTiket':'Penumpang','golonganTiket':adult,'kelasKondisi':None}
base={'combination':key,'basisKomisi':1000000,'persentaseLama':'5,00','persentaseBaru':'7,50','komisiLama':50000,'komisiBaru':75000,'fixtureIsolation':'reset per scenario; gunakan database uji; agen A/B memiliki izin rute sama, agen C tidak memiliki izin rute ini'}
def st(a,t,v=''): return {'action':a,'target':t,'value':v}
def click(t): return st('click',t)
def fill(t,v): return st('fill',t,v)
def select(t,v): return st('select',t,v)
def expect(t,v): return st('expect',t,v)
def nav(t): return st('navigate',t,t)
def add(n,cat,title,screen,pre,steps,expected=None,data=None,priority='high'):
    counts=collections.Counter(x['category'] for x in S)
    ident=f"{M.upper()}-"+{'positive':'POS','negative':'NEG','edge':'EDG','stress':'STR'}[cat]+f"-{counts[cat]+1:03}"
    hints={screen:{'role':'heading','name':screen,'testid':f'ro316-screen-{screen}'}}
    for x in steps:
        target=x['target']
        hint=UI.get(screen,{}).get(target)
        if not hint:
            hint=next((v[target] for v in UI.values() if target in v),None)
        if not hint:
            role={'click':'button','select':'combobox','fill':'textbox','navigate':'heading','expect':'generic'}[x['action']]
            hint={'role':role,'name':target,'testid':'ro316-proposed-'+re.sub(r'[^a-z0-9]+','-',target.lower()).strip('-')}
        hints[target]=dict(hint)
    d=dict(base)
    combination=dict(key)
    mapping={'Rute':'rute','Jenis Tiket':'jenisTiket','Golongan Tiket':'golonganTiket','Kelas / Kondisi Kendaraan':'kelasKondisi'}
    for step in steps:
        if step['action']=='select' and step['target'] in mapping:
            combination[mapping[step['target']]]=step['value']
        if step['action']=='select' and step['target']=='Jenis Tiket' and step['value']=='Penumpang':
            combination['kelasKondisi']=None
    d['combination']=combination
    d.update(data or {})
    S.append({'id':ident,'title':title,'category':cat,'priority':priority,'requirement':f'REQ-{n:03}','screen':screen,'preconditions':['Fixture uji terisolasi telah disiapkan; alias URL dan selector sudah dipetakan ke aplikasi.']+pre,'steps':[nav(screen)]+steps,'expected':expected or [x['target']+': '+x['value'] for x in steps if x['action']=='expect'],'testData':d,'selectorHints':hints})
