LIST='master-komisi-agen';DET='setting-komisi-rute';RO='komisi-rute';ADD='tambah-komisi-agen';EDIT='edit-komisi-agen';SALE='transaksi-agen';OLD='detail-transaksi'
def form(pct='5,00',jenis='Penumpang',gol=adult,kelas=None):
    steps=[select('Jenis Tiket',jenis),select('Golongan Tiket',gol)]
    if kelas is not None: steps.append(select('Kelas / Kondisi Kendaraan',kelas))
    return steps+[fill('% Komisi',pct)]
def sell(): return [select('Rute',route),select('Jenis Tiket','Penumpang'),select('Golongan Tiket',adult),click('Buat Transaksi')]
