summary={'total':len(S),**{k:sum(x['category']==k for x in S) for k in [P,N,E,T]}}
payload={'summary':summary,'source':{'spec':f'inputs/{M}/spec.txt','designs':[],'extras':[f'inputs/{M}/extras/desain-ro-1-5-4-master-komisi-agen.html']},'scenarios':S}
(OUT/f'{M}.scenarios.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def q(s):return '"'+str(s).replace('\\','\\\\').replace('"','\\"').replace('\n','\\n')+'"'
lines=['# language: en',f'Feature: {M}','  Pengaturan komisi general per rute oleh Kantor Pusat dengan akses Cabang read-only.','']
for x in S:
    lines += [f"  @{x['category']} @priority-{x['priority']} @{x['requirement']} @screen-{x['screen']} @id-{x['id']}",f"  Scenario: {x['id']} — {x['title']}"]
    for i,p in enumerate(x['preconditions']): lines.append(('    Given ' if i==0 else '    And ')+'prasyarat '+q(p)+' terpenuhi')
    lines.append('    And user berada di halaman '+q(x['screen']))
    first=True;then=False
    for step in x['steps'][1:]:
        a,t,v=step.values()
        if a=='expect':
            prefix='Then' if not then else 'And';then=True
            body='sistem memverifikasi elemen '+q(t)+' dengan hasil '+q(v)
        else:
            prefix='When' if first else 'And';first=False
            element_kind='tautan' if x['selectorHints'][t]['role']=='link' else 'tombol'
            body={'click':lambda:'user mengklik '+element_kind+' '+q(t),'fill':lambda:'user mengisi field '+q(t)+' dengan '+q(v),'select':lambda:'user memilih opsi '+q(v)+' pada field '+q(t)}[a]()
            # Ketika assertion diselingi aksi baru, mulai When agar urutan Gherkin tetap jelas.
            if then: prefix='When'; then=False
        lines.append('    '+prefix+' '+body)
    lines.append('')
(OUT/f'{M}.feature').write_text('\n'.join(lines),encoding='utf-8')
print(json.dumps(summary))
